"use client";

import { EyeIcon, EyeSlashIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { duration, easeOut } from "./motion";
import { Button } from "./button";
import { fieldTriggerStyles } from "./field-styles";
import { InputGroup, InputGroupAddon, InputGroupInput } from "./input-group";
import {
  TextField,
  TextFieldDescription,
  TextFieldError,
  TextFieldLabel,
  type TextFieldProps,
} from "./text-field";

export interface PasswordFieldProps
  extends Omit<TextFieldProps, "children" | "label" | "type"> {
  label: string;
}

export function PasswordField({
  label,
  description,
  placeholder,
  isDisabled,
  autoComplete = "current-password",
  ...props
}: PasswordFieldProps) {
  const [visible, setVisible] = useState(false);
  const [pointerReveal, setPointerReveal] = useState(false);
  const reduceMotion = useReducedMotion();
  const iconTransition = {
    duration: reduceMotion || !pointerReveal ? 0 : duration.fast,
    ease: easeOut,
  };

  return (
    <TextField
      {...props}
      type={visible ? "text" : "password"}
      autoComplete={autoComplete}
      isDisabled={isDisabled}
    >
      <TextFieldLabel>{label}</TextFieldLabel>
      <InputGroup className="pe-1">
        <InputGroupInput placeholder={placeholder} />
        <InputGroupAddon>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className={fieldTriggerStyles}
            isDisabled={isDisabled}
            aria-label={visible ? "Hide password" : "Show password"}
            aria-pressed={visible}
            onPress={(event) => {
              setPointerReveal(
                event.pointerType === "mouse" ||
                  event.pointerType === "touch" ||
                  event.pointerType === "pen",
              );
              setVisible((current) => !current);
            }}
          >
            <span
              className="relative grid size-5 place-items-center"
              aria-hidden="true"
            >
              <motion.span
                className="col-start-1 row-start-1"
                initial={false}
                animate={{ opacity: visible ? 0 : 1, scale: visible ? 0.9 : 1 }}
                transition={iconTransition}
              >
                <EyeIcon size={18} />
              </motion.span>
              <motion.span
                className="col-start-1 row-start-1"
                initial={false}
                animate={{ opacity: visible ? 1 : 0, scale: visible ? 1 : 0.9 }}
                transition={iconTransition}
              >
                <EyeSlashIcon size={18} />
              </motion.span>
            </span>
          </Button>
        </InputGroupAddon>
      </InputGroup>
      {description && (
        <TextFieldDescription>{description}</TextFieldDescription>
      )}
      <TextFieldError />
    </TextField>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Meter as AriaMeter,
  type MeterProps as AriaMeterProps,
  composeRenderProps,
  Label,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export interface MeterProps
  extends Omit<AriaMeterProps, "className" | "children"> {
  label?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaMeterProps["className"];
  children?: AriaMeterProps["children"];
}

export function Meter({ label, className, children, ...props }: MeterProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaMeter
      {...props}
      data-slot="meter"
      className={composeRenderProps(className, (className) =>
        cn("grid w-full gap-2", className),
      )}
    >
      {children ??
        (({ percentage, valueText }) => (
          <>
            <div className="flex items-baseline gap-3 text-sm">
              {label && (
                <Label
                  data-slot="meter-label"
                  className="min-w-0 font-medium [overflow-wrap:anywhere]"
                >
                  {label}
                </Label>
              )}
              <span
                data-slot="meter-value"
                className="ms-auto min-w-0 text-end font-mono tabular-nums text-muted-foreground"
              >
                {valueText}
              </span>
            </div>
            <div
              data-slot="meter-track"
              className="h-2 overflow-hidden rounded-full bg-secondary shadow-[var(--shadow-inset)] forced-colors:border rtl:-scale-x-100"
            >
              <motion.div
                data-slot="meter-fill"
                className="h-full w-full origin-left rounded-full bg-primary forced-colors:bg-[Highlight]"
                initial={false}
                animate={{ scaleX: percentage / 100 }}
                transition={{
                  duration: reduceMotion ? 0 : duration.base,
                  ease: easeOut,
                }}
              />
            </div>
          </>
        ))}
    </AriaMeter>
  );
}

"use client";

import { Meter, type MeterProps } from "./meter";

export interface PasswordStrengthMeterProps {
  password: string;
  className?: MeterProps["className"];
}

export function PasswordStrengthMeter({
  password,
  className,
}: PasswordStrengthMeterProps) {
  const score =
    Number(password.length >= 8) +
    Number(password.length >= 12) +
    Number(password.length >= 16) +
    Number(/[a-zA-Z]/.test(password) && /[0-9\W_]/.test(password));

  return (
    <Meter
      className={className}
      label="Password strength"
      value={score}
      minValue={0}
      maxValue={4}
      valueLabel={password ? `${score} of 4 checks met` : "No password yet"}
    />
  );
}

